artifacts.solve_py:
import csv, json, math, os, sys, itertools

from pyscipopt import Model, quicksum

APP = "/app"
DATA = os.path.join(APP, "data")
SUB = os.path.join(APP, "submissions")
os.makedirs(SUB, exist_ok=True)

# ---------------- Load data ----------------
with open(os.path.join(DATA, "config.json")) as f:
    cfg = json.load(f)

bases = []
with open(os.path.join(DATA, "candidate_bases.csv")) as f:
    for row in csv.DictReader(f):
        bases.append({
            "id": row["base_id"], "region": row["region"],
            "x": float(row["x_km"]), "y": float(row["y_km"]),
            "fixed": float(row["fixed_cost"]), "max_drones": int(row["max_drones"]),
            "kit_cap": int(row["kit_capacity"]), "launch": float(row["launch_delay_min"]),
            "range": float(row["range_km"]), "wh": int(row["weather_hardened"]),
        })
B = [b["id"] for b in bases]
Binfo = {b["id"]: b for b in bases}

zones = []
with open(os.path.join(DATA, "demand_zones.csv")) as f:
    for row in csv.DictReader(f):
        zones.append({
            "id": row["zone_id"], "district": row["district"], "group": row["equity_group"],
            "x": float(row["x_km"]), "y": float(row["y_km"]), "calls": float(row["base_calls_per_day"]),
            "risk": float(row["risk_weight"]), "ems": float(row["baseline_ems_min"]),
            "hp": int(row["priority_zone"]),
        })
Z = [z["id"] for z in zones]
Zinfo = {z["id"]: z for z in zones}

scen = []
with open(os.path.join(DATA, "scenarios.csv")) as f:
    for row in csv.DictReader(f):
        scen.append({
            "id": row["scenario_id"], "p": float(row["probability"]),
            "cm": float(row["call_multiplier"]), "vm": float(row["drone_speed_multiplier"]),
            "gm": float(row["ground_time_multiplier"]), "kr": float(row["kit_reserve_factor"]),
            "nofly": int(row["no_fly"]), "sev": int(row["weather_severity"]),
        })
S = [s["id"] for s in scen]
Sinfo = {s["id"]: s for s in scen}

equity = {}
with open(os.path.join(DATA, "equity_requirements.csv")) as f:
    for row in csv.DictReader(f):
        equity[row["equity_group"]] = {
            "target": float(row["response_target_min"]),
            "minshare": float(row["min_fast_share"]),
            "tailshare": float(row["tail_min_fast_share"]),
        }

ground_cap = {}
with open(os.path.join(DATA, "district_ground_capacity.csv")) as f:
    for row in csv.DictReader(f):
        ground_cap[(row["scenario_id"], row["district"])] = float(row["max_ground_calls_per_day"])

# corridor rules: scenario-specific overrides ALL
cor_all = {}
cor_spec = {}
with open(os.path.join(DATA, "air_corridor_rules.csv")) as f:
    for row in csv.DictReader(f):
        key = (row["origin_region"], row["destination_district"])
        rec = (float(row["max_calls_per_day"]), float(row["extra_minutes"]), int(row["requires_weather_hardened"]))
        if row["scenario_id"] == "ALL":
            cor_all[key] = rec
        else:
            cor_spec[(row["scenario_id"],) + key] = rec

def corridor(s, region, district):
    key = (s, region, district)
    if key in cor_spec:
        return cor_spec[key]
    return cor_all.get((region, district))

exceptions = set()
with open(os.path.join(DATA, "base_zone_exceptions.csv")) as f:
    for row in csv.DictReader(f):
        if int(row["allowed"]) == 0:
            exceptions.add((row["scenario_id"], row["base_id"], row["zone_id"]))

staff = {}
with open(os.path.join(DATA, "base_region_staffing.csv")) as f:
    for row in csv.DictReader(f):
        staff[row["region"]] = (int(row["max_open_bases"]), int(row["max_drones"]))

# ---------------- Derived quantities ----------------
W = cfg["weights"]
SPEED = cfg["base_drone_speed_kmph"]
SERVICE = cfg["service_minutes_at_scene"]
RELOAD = cfg["reload_minutes"]
DAILY_MIN = cfg["daily_service_hours"] * 60.0  # 1080
UTIL = cfg["max_queue_utilization"]
BUDGET = cfg["weekly_budget"]
DRONE_COST = cfg["drone_weekly_cost"]
KIT_COST = cfg["kit_unit_cost"]
TOTAL_DRONES = cfg["total_drones_available"]
MAX_OPEN = cfg["max_open_bases"]
MIN_OPEN = cfg["min_open_bases"]
GROUND_SHARE = cfg["max_ground_share_flyable"]
DECAY = cfg["death_risk_decay_per_minute"]
TAIL_N = cfg["tail_scenario_count"]

def dist(b, z):
    return math.hypot(Binfo[b]["x"] - Zinfo[z]["x"], Binfo[b]["y"] - Zinfo[z]["y"])

# tail scenarios = 2 worst by stress (highest weather severity, then speed reduction)
tail_scen = sorted(S, key=lambda s: (-Sinfo[s]["sev"], -Sinfo[s]["cm"]))[:TAIL_N]

# Eligibility: drone (s,z,b)
# eligible if: not no-fly, dist <= range, no ALL exception, no scenario exception,
# corridor exists, and if corridor requires weather hardened then base is hardened.
elig = {}          # (s,z) -> list of bases
dtime = {}         # (s,z,b) -> drone response minutes (launch + flight + service)
cextra = {}        # (s,z,b) -> corridor extra minutes
percall = {}       # (s,z,b) -> minutes of base occupancy per call (round trip + service + reload + launch)
for s in S:
    si = Sinfo[s]
    for z in Z:
        zi = Zinfo[z]
        lst = []
        if si["nofly"] == 1:
            elig[(s, z)] = lst
            continue
        for b in B:
            bi = Binfo[b]
            d = dist(b, z)
            if d > bi["range"] + 1e-9:
                continue
            if ("ALL", b, z) in exceptions or (s, b, z) in exceptions:
                continue
            cor = corridor(s, bi["region"], zi["district"])
            if cor is None:
                continue
            cap, extra, whreq = cor
            if whreq == 1 and bi["wh"] == 0:
                continue
            speed = SPEED * si["vm"]
            flight = d / speed * 60.0
            rt = bi["launch"] + flight + SERVICE + extra
            pc = bi["launch"] + 2.0 * flight + SERVICE + RELOAD
            lst.append(b)
            dtime[(s, z, b)] = rt
            cextra[(s, z, b)] = extra
            percall[(s, z, b)] = pc
        elig[(s, z)] = lst

# ground response time per (s,z)
gtime = {}
for s in S:
    si = Sinfo[s]
    for z in Z:
        gtime[(s, z)] = si["gm"] * Zinfo[z]["ems"]

# fast flags for equity
def drone_fast(s, z, b, g):
    return dtime.get((s, z, b), 1e9) <= equity[g]["target"] + 1e-9

def ground_fast(s, z, g):
    return gtime[(s, z)] <= equity[g]["target"] + 1e-9

# ---------------- Model ----------------
model = Model("naloxone_drone")
model.setParam("gaprel", 0.0005)
time_limit = 300.0
env = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
if env is not None:
    try:
        time_limit = min(time_limit, float(env))
    except ValueError:
        pass
model.setParam("limits/time", time_limit)

y = {}
for b in B:
    y[b] = model.addVar(name=f"y_{b}", vtype="B", lb=0, ub=1, obj=0.0)
u = {}
for b in B:
    u[b] = model.addVar(name=f"u_{b}", vtype="I", lb=0, ub=Binfo[b]["max_drones"], obj=0.0)
q = {}
for b in B:
    q[b] = model.addVar(name=f"q_{b}", vtype="I", lb=0, ub=Binfo[b]["kit_cap"], obj=0.0)

x = {}
for s in S:
    for z in Z:
        for b in elig[(s, z)]:
            x[(s, z, b)] = model.addVar(name=f"x_{s}_{z}_{b}", vtype="B", lb=0, ub=1, obj=0.0)
g = {}
for s in S:
    for z in Z:
        g[(s, z)] = model.addVar(name=f"g_{s}_{z}", vtype="B", lb=0, ub=1, obj=0.0)
w = {}
for s in S:
    if Sinfo[s]["nofly"] == 1:
        continue
    for z in Z:
        if Zinfo[z]["hp"] != 1:
            continue
        for b in elig[(s, z)]:
            w[(s, z, b)] = model.addVar(name=f"w_{s}_{z}_{b}", vtype="B", lb=0, ub=1, obj=0.0)
fast = {}
for s in S:
    for z in Z:
        fast[(s, z)] = model.addVar(name=f"fast_{s}_{z}", vtype="B", lb=0, ub=1, obj=0.0)
prio = {}
for s in S:
    for z in Z:
        prio[(s, z)] = model.addVar(name=f"p_{s}_{z}", vtype="I", lb=1, ub=3, obj=0.0)

# ---- structural constraints ----
model.addCons(quicksum(y[b] for b in B) >= MIN_OPEN, name="min_open")
model.addCons(quicksum(y[b] for b in B) <= MAX_OPEN, name="max_open")
model.addCons(quicksum(u[b] for b in B) <= TOTAL_DRONES, name="fleet")
for r in staff:
    rb = [b for b in B if Binfo[b]["region"] == r]
    mo, md = staff[r]
    model.addCons(quicksum(y[b] for b in rb) <= mo, name=f"open_{r}")
    model.addCons(quicksum(u[b] for b in rb) <= md, name=f"drones_{r}")
for b in B:
    model.addCons(u[b] <= Binfo[b]["max_drones"] * y[b], name=f"link_u_{b}")
    model.addCons(q[b] <= Binfo[b]["kit_cap"] * y[b], name=f"link_q_{b}")

# budget
model.addCons(
    quicksum(Binfo[b]["fixed"] * y[b] for b in B)
    + DRONE_COST * quicksum(u[b] for b in B)
    + KIT_COST * quicksum(q[b] for b in B) <= BUDGET, name="budget")

# dispatch: exactly one
for s in S:
    for z in Z:
        lhs = g[(s, z)] + quicksum(x[(s, z, b)] for b in elig[(s, z)])
        model.addCons(lhs == 1, name=f"disp_{s}_{z}")

# corridor aggregate caps: sum calls routed region->district <= cap
for s in S:
    si = Sinfo[s]
    for (region, district), (cap, extra, whreq) in cor_all.items():
        cap_s, extra_s, whreq_s = corridor(s, region, district)
        terms = []
        for z in Z:
            if Zinfo[z]["district"] != district:
                continue
            for b in elig[(s, z)]:
                if Binfo[b]["region"] != region:
                    continue
                terms.append(Zinfo[z]["calls"] * si["cm"] * x[(s, z, b)])
        if terms:
            model.addCons(quicksum(terms) <= cap_s, name=f"cor_{s}_{region}_{district}")

# ground district caps
for s in S:
    si = Sinfo[s]
    for d in set(z["district"] for z in zones):
        cap = ground_cap.get((s, d), 0.0)
        terms = [Zinfo[z]["calls"] * si["cm"] * g[(s, z)] for z in Z if Zinfo[z]["district"] == d]
        model.addCons(quicksum(terms) <= cap + 1e-9, name=f"ground_{s}_{d}")

# citywide ground share in flyable scenarios
for s in S:
    if Sinfo[s]["nofly"] == 1:
        continue
    si = Sinfo[s]
    total = sum(Zinfo[z]["calls"] * si["cm"] for z in Z)
    model.addCons(
        quicksum(Zinfo[z]["calls"] * si["cm"] * g[(s, z)] for z in Z)
        <= GROUND_SHARE * total + 1e-9, name=f"gshare_{s}")

# backup requirements
for s in S:
    if Sinfo[s]["nofly"] == 1:
        continue
    for z in Z:
        if Zinfo[z]["hp"] != 1:
            continue
        e = elig[(s, z)]
        model.addCons(quicksum(w[(s, z, b)] for b in e) == quicksum(x[(s, z, b)] for b in e),
                      name=f"bkup_cnt_{s}_{z}")
        for b in e:
            model.addCons(w[(s, z, b)] <= y[b], name=f"bkup_open_{s}_{z}_{b}")
            model.addCons(w[(s, z, b)] <= 1 - x[(s, z, b)], name=f"bkup_diff_{s}_{z}_{b}")

# queueing utilization: load * per-call minutes <= UTIL * DAILY_MIN * u_b
# per-call minutes vary by zone; use per (s,b) aggregated: sum_z calls*cm*pc * x <= UTIL*1080*u
for s in S:
    si = Sinfo[s]
    for b in B:
        terms = []
        for z in Z:
            if (s, z, b) not in x:
                continue
            terms.append(Zinfo[z]["calls"] * si["cm"] * percall[(s, z, b)] * x[(s, z, b)])
        if terms:
            model.addCons(quicksum(terms) <= UTIL * DAILY_MIN * u[b], name=f"util_{s}_{b}")
        else:
            model.addCons(u[b] >= 0, name=f"util_{s}_{b}")

# kits cover worst scenario-adjusted load with reserve
for b in B:
    for s in S:
        si = Sinfo[s]
        terms = [Zinfo[z]["calls"] * si["cm"] * x[(s, z, b)] for z in Z if (s, z, b) in x]
        rhs = si["kr"] * (quicksum(terms) if terms else 0)
        model.addCons(q[b] >= rhs, name=f"kits_{s}_{b}")

# equity fast share
for s in S:
    for z in Z:
        zi = Zinfo[z]
        gvar = fast[(s, z)]
        for b in elig[(s, z)]:
            if drone_fast(s, z, b, zi["group"]):
                model.addCons(gvar >= x[(s, z, b)], name=f"fastd_{s}_{z}_{b}")
        if ground_fast(s, z, zi["group"]):
            model.addCons(gvar >= g[(s, z)], name=f"fastg_{s}_{z}")
        # upper bound: fast only if served by a fast option
        up = [x[(s, z, b)] for b in elig[(s, z)] if drone_fast(s, z, b, zi["group"])]
        if ground_fast(s, z, zi["group"]):
            up.append(g[(s, z)])
        if up:
            model.addCons(gvar <= quicksum(up), name=f"fastub_{s}_{z}")
        else:
            model.addCons(gvar == 0, name=f"fastub_{s}_{z}")

# probability-weighted expected share per group
for grp, eq in equity.items():
    zgrp = [z for z in Z if Zinfo[z]["group"] == grp]
    lhs = quicksum(Sinfo[s]["p"] * Zinfo[z]["calls"] * Sinfo[s]["cm"] * fast[(s, z)]
                   for s in S for z in zgrp)
    rhs = eq["minshare"] * quicksum(Sinfo[s]["p"] * Zinfo[z]["calls"] * Sinfo[s]["cm"]
                                    for s in S for z in zgrp)
    model.addCons(lhs >= rhs - 1e-9, name=f"eq_exp_{grp}")
# tail scenarios per-scenario share
for grp, eq in equity.items():
    zgrp = [z for z in Z if Zinfo[z]["group"] == grp]
    for s in tail_scen:
        si = Sinfo[s]
        lhs = quicksum(Zinfo[z]["calls"] * si["cm"] * fast[(s, z)] for z in zgrp)
        rhs = eq["tailshare"] * quicksum(Zinfo[z]["calls"] * si["cm"] for z in zgrp)
        model.addCons(lhs >= rhs - 1e-9, name=f"eq_tail_{grp}_{s}")

# priority: hp zones get priority 1 in flyable scenarios (deterministic rule to fix integrality)
for s in S:
    for z in Z:
        if Zinfo[z]["hp"] == 1 and Sinfo[s]["nofly"] == 0:
            model.addCons(prio[(s, z)] == 1, name=f"prio_hp_{s}_{z}")

# ---------------- Objective ----------------
# response time per (s,z): min over drone options, or ground time
# linear: RT_{s,z} = sum_b rt_b x_b + gt g  (exactly one dispatch so this equals the chosen RT)
exp_resp = 0.0
tail_resp = 0.0
mortality = 0.0
ground_share_obj = 0.0
total_callprob = sum(Sinfo[s]["p"] * Zinfo[z]["calls"] * Sinfo[s]["cm"] for s in S for z in Z)
for s in S:
    si = Sinfo[s]
    for z in Z:
        zi = Zinfo[z]
        rt_terms = [dtime[(s, z, b)] * x[(s, z, b)] for b in elig[(s, z)]]
        rt_terms.append(gtime[(s, z)] * g[(s, z)])
        rt = quicksum(rt_terms)
        wcall = si["p"] * zi["calls"] * si["cm"]
        exp_resp += wcall * rt
        if s in tail_scen:
            tail_resp += zi["calls"] * si["cm"] * rt
        # mortality proxy: risk * max(0, 1 - decay*RT); linearize with aux var m >= 1 - decay*RT, m >= 0
        mvar = model.addVar(name=f"m_{s}_{z}", vtype="C", lb=0.0, ub=1.0, obj=0.0)
        model.addCons(mvar >= 1.0 - DECAY * rt, name=f"mlb_{s}_{z}")
        mortality += wcall * zi["risk"] * mvar
        ground_share_obj += wcall * g[(s, z)]

tail_denom = sum(Zinfo[z]["calls"] * Sinfo[s]["cm"] for s in tail_scen for z in Z)
tail_resp_avg = tail_resp / TAIL_N  # average per tail scenario (divide by TAIL_N of scenario totals)

# equity gap aux: gap_g >= minshare - expected share
gap_terms = 0.0
for grp, eq in equity.items():
    zgrp = [z for z in Z if Zinfo[z]["group"] == grp]
    exp_share = quicksum(Sinfo[s]["p"] * Zinfo[z]["calls"] * Sinfo[s]["cm"] * fast[(s, z)]
                         for s in S for z in zgrp)
    denom = quicksum(Sinfo[s]["p"] * Zinfo[z]["calls"] * Sinfo[s]["cm"] for s in S for z in zgrp)
    gap = model.addVar(name=f"gap_{grp}", vtype="C", lb=0.0, ub=1.0, obj=0.0)
    model.addCons(gap >= eq["minshare"] * denom - exp_share, name=f"gaplb_{grp}")
    gap_terms += gap

cost_obj = (quicksum(Binfo[b]["fixed"] * y[b] for b in B)
            + DRONE_COST * quicksum(u[b] for b in B)
            + KIT_COST * quicksum(q[b] for b in B))

obj = (W["weekly_cost"] * cost_obj
       + W["expected_response_minutes"] * exp_resp / total_callprob
       + W["tail_response_minutes"] * tail_resp_avg / total_callprob * TAIL_N
       + W["mortality_risk"] * mortality / total_callprob
       + W["equity_gap"] * gap_terms
       + W["ground_fallback"] * ground_share_obj / total_callprob)
model.setObjective(obj, sense="minimize")

# ---------------- Solve ----------------
status = "unknown"
objval = None
try:
    model.optimize()
    status = model.getStatus()
    nsols = model.getNSols()
    print(f"SCIP status: {status}, nsols={nsols}, time={model.getOrigTime():.2f}s" if hasattr(model, "getOrigTime") else f"SCIP status: {status}, nsols={nsols}")
    if nsols > 0:
        sol = model.getBestSol()
        objval = model.getObjVal()
        print(f"Objective: {objval:.6f}")
except Exception as e:
    print(f"Solver error: {e}")
    status = "error"

# ---------------- Extract solution ----------------
Y = {b: 0 for b in B}
U = {b: 0 for b in B}
Q = {b: 0 for b in B}
X = {}
G = {}
Wb = {}
P = {}
if model.getNSols() > 0:
    for b in B:
        Y[b] = int(round(model.getVal(y[b])))
        U[b] = int(round(model.getVal(u[b])))
        Q[b] = int(round(model.getVal(q[b])))
    for s in S:
        for z in Z:
            best = None
            for b in elig[(s, z)]:
                v = model.getVal(x[(s, z, b)])
                if v is not None and v > 0.5:
                    best = b
                    break
            if best is None:
                gv = model.getVal(g[(s, z)])
                if gv is not None and gv > 0.5:
                    best = "ground"
                else:
                    # fallback: pick any eligible base or ground
                    best = elig[(s, z)][0] if elig[(s, z)] else "ground"
            X[(s, z)] = best
            if best == "ground":
                G[(s, z)] = 1
            else:
                G[(s, z)] = 0
                if Sinfo[s]["nofly"] == 0 and Zinfo[z]["hp"] == 1:
                    bk = None
                    for b in elig[(s, z)]:
                        if b == best:
                            continue
                        wv = model.getVal(w[(s, z, b)])
                        if wv is not None and wv > 0.5:
                            bk = b
                            break
                    if bk is None:
                        for b in elig[(s, z)]:
                            if b != best and Y[b] == 1:
                                bk = b
                                break
                    Wb[(s, z)] = bk
            pv = model.getVal(prio[(s, z)])
            P[(s, z)] = int(round(pv)) if pv is not None else (1 if Zinfo[z]["hp"] else 2)
else:
    # heuristic fallback: open 4 cheapest feasible bases, serve by nearest, ground where needed
    print("No SCIP solution; using heuristic fallback.")
    for b in B:
        Y[b] = 0
    chosen = sorted(B, key=lambda b: Binfo[b]["fixed"])[:MIN_OPEN]
    for b in chosen:
        Y[b] = 1
        U[b] = min(Binfo[b]["max_drones"], 3)
        Q[b] = Binfo[b]["kit_cap"]
    for s in S:
        for z in Z:
            cands = [b for b in elig[(s, z)] if Y[b] == 1]
            if cands:
                best = min(cands, key=lambda b: dtime[(s, z, b)])
                X[(s, z)] = best
                G[(s, z)] = 0
                if Sinfo[s]["nofly"] == 0 and Zinfo[z]["hp"] == 1:
                    bk = next((b for b in cands if b != best), None)
                    Wb[(s, z)] = bk
                else:
                    Wb[(s, z)] = None
            else:
                X[(s, z)] = "ground"
                G[(s, z)] = 1
                Wb[(s, z)] = None
            P[(s, z)] = 1 if Zinfo[z]["hp"] else 2

# ---------------- Validation ----------------
ok = True
def check(cond, msg):
    global ok
    if not cond:
        ok = False
        print(f"FAIL: {msg}")

open_bases = [b for b in B if Y[b] == 1]
check(MIN_OPEN <= len(open_bases) <= MAX_OPEN, f"open bases {len(open_bases)}")
check(sum(U.values()) <= TOTAL_DRONES, "fleet cap")
for b in B:
    check(U[b] <= Binfo[b]["max_drones"] * Y[b], f"u link {b}")
    check(Q[b] <= Binfo[b]["kit_cap"] * Y[b], f"q link {b}")
    check(0 <= U[b] and 0 <= Q[b], f"nonneg {b}")
cost = sum(Binfo[b]["fixed"] * Y[b] for b in B) + DRONE_COST * sum(U.values()) + KIT_COST * sum(Q.values())
check(cost <= BUDGET + 1e-6, f"budget {cost}")

n_dispatch = 0
for s in S:
    si = Sinfo[s]
    for z in Z:
        n_dispatch += 1
        b = X[(s, z)]
        if b == "ground":
            check(G[(s, z)] == 1, f"ground flag {s},{z}")
        else:
            check(Y[b] == 1, f"drone base open {s},{z},{b}")
            check((s, z, b) in dtime, f"drone eligible {s},{z},{b}")
            if si["nofly"] == 0 and Zinfo[z]["hp"] == 1:
                bk = Wb.get((s, z))
                check(bk is not None and bk != b and Y[bk] == 1 and (s, z, bk) in dtime,
                      f"backup {s},{z}")
        check(1 <= P[(s, z)] <= 3, f"priority {s},{z}")
check(n_dispatch == len(S) * len(Z), "dispatch row count")

# corridor / ground / utilization / kit numeric checks
for s in S:
    si = Sinfo[s]
    for (region, district) in cor_all:
        cap_s, extra_s, whreq_s = corridor(s, region, district)
        load = 0.0
        for z in Z:
            if Zinfo[z]["district"] != district:
                continue
            b = X[(s, z)]
            if b != "ground" and Binfo[b]["region"] == region:
                load += Zinfo[z]["calls"] * si["cm"]
        check(load <= cap_s + 1e-6, f"corridor {s},{region},{district}: {load} > {cap_s}")
    for d in set(z["district"] for z in zones):
        cap = ground_cap.get((s, d), 0.0)
        load = sum(Zinfo[z]["calls"] * si["cm"] for z in Z
                   if Zinfo[z]["district"] == d and X[(s, z)] == "ground")
        check(load <= cap + 1e-6, f"ground cap {s},{d}: {load} > {cap}")
    if si["nofly"] == 0:
        total = sum(Zinfo[z]["calls"] * si["cm"] for z in Z)
        gl = sum(Zinfo[z]["calls"] * si["cm"] for z in Z if X[(s, z)] == "ground")
        check(gl <= GROUND_SHARE * total + 1e-6, f"ground share {s}: {gl/total:.3f}")
for b in B:
    for s in S:
        si = Sinfo[s]
        loadmin = 0.0
        loadc = 0.0
        for z in Z:
            if X[(s, z)] == b:
                loadc += Zinfo[z]["calls"] * si["cm"]
                loadmin += Zinfo[z]["calls"] * si["cm"] * percall[(s, z, b)]
        if loadc > 0:
            check(loadmin <= UTIL * DAILY_MIN * U[b] + 1e-6, f"util {s},{b}")
            check(Q[b] >= si["kr"] * loadc - 1e-6, f"kits {s},{b}")

# equity checks
for grp, eq in equity.items():
    zgrp = [z for z in Z if Zinfo[z]["group"] == grp]
    num = 0.0
    den = 0.0
    for s in S:
        si = Sinfo[s]
        for z in zgrp:
            wcall = si["p"] * Zinfo[z]["calls"] * si["cm"]
            den += wcall
            b = X[(s, z)]
            isfast = False
            if b != "ground":
                isfast = dtime[(s, z, b)] <= eq["target"] + 1e-9
            else:
                isfast = gtime[(s, z)] <= eq["target"] + 1e-9
            if isfast:
                num += wcall
    share = num / den if den > 0 else 1.0
    check(share >= eq["minshare"] - 1e-6, f"equity exp {grp}: {share:.3f} < {eq['minshare']}")
    for s in tail_scen:
        si = Sinfo[s]
        tn = 0.0
        td = 0.0
        for z in zgrp:
            wcall = Zinfo[z]["calls"] * si["cm"]
            td += wcall
            b = X[(s, z)]
            isfast = (dtime[(s, z, b)] <= eq["target"] + 1e-9) if b != "ground" \
                else (gtime[(s, z)] <= eq["target"] + 1e-9)
            if isfast:
                tn += wcall
        tshare = tn / td if td > 0 else 1.0
        check(tshare >= eq["tailshare"] - 1e-6, f"equity tail {grp},{s}: {tshare:.3f} < {eq['tailshare']}")

